from datetime import datetime

def it(p):
    for w in p.get('events') or []:
        e=(w or {}).get('event') or {}
        if e.get('status')=='cancelled':
            continue
        s,e2=(e.get('start') or {}),(e.get('end') or {})
        if 'date' in s or 'date' in e2:
            continue
        sd,ed=s.get('dateTime'),e2.get('dateTime')
        if not sd or not ed:
            continue
        yield datetime.fromisoformat(sd.replace('Z','+00:00')),datetime.fromisoformat(ed.replace('Z','+00:00'))

def total_hours(p):
    return sum(max(0,(b-a).total_seconds()) for a,b in it(p))/3600.0
